command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/release-source-identity-20261006"
$candidate="911940b18120077c05759d8d4b9be90e1d6f3f86"
$baseline="6b91eaee6c268b422f21a83570e37dc9be2ed961"
$accepted="28e361e8d9f3ed796abe7f69a4f301ae6e52a002"
$source="bc63c8b48e466d1275cc6dcffb0c50e02d39db60"
$temp=Join-Path $env:RUNNER_TEMP ("release-source-docs-final-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $baseline){throw "main moved before release-source docs validation: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before release-source docs validation: $branchSha"}

  & git merge-base --is-ancestor $source $candidate
  if($LASTEXITCODE -ne 0){throw "binary source revision is not an ancestor of final candidate"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check $baseline $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & git diff --quiet $accepted $candidate -- packaging/licenses packaging/RELEASE_IDENTITY.json packaging/SOURCE_BUNDLE_MANIFEST.json packaging/source_bundle.py packaging/release_identity.py tests/winui/test_release_source_bundle_contract.py
  if($LASTEXITCODE -ne 0){throw "accepted release identity records or implementation changed after #440"}

  & cmd /c test.bat policy
  if($LASTEXITCODE -ne 0){throw "policy validation failed"}

  & python -X utf8 -m unittest tests.winui.test_release_source_bundle_contract tests.winui.test_release_payload_contract tests.winui.test_installer_contract
  if($LASTEXITCODE -ne 0){throw "release source/package contracts failed"}

  $identity=Get-Content -Raw -Encoding UTF8 -LiteralPath "packaging\RELEASE_IDENTITY.json" | ConvertFrom-Json
  $manifest=Get-Content -Raw -Encoding UTF8 -LiteralPath "packaging\SOURCE_BUNDLE_MANIFEST.json" | ConvertFrom-Json
  if($identity.binary_source_revision -ne $source){throw "tracked release identity source revision mismatch"}
  if($manifest.source_revision -ne $source){throw "tracked source bundle manifest revision mismatch"}
  if($identity.source_bundle.sha256 -ne "5a263a42ecced3384be9a8ab131024ce309e4eb96b249bad1f8adc91f065ce1d"){throw "tracked source bundle digest mismatch"}
  if($identity.runtime.manifest_sha256 -ne "61572e65c4a593e01607147596195041ce9d530e5f9fc21c9f9517f615b26c1d"){throw "tracked runtime digest mismatch"}
  if($identity.setup.sha256 -ne "825a644a8170acdaae43135604d6998ce517f882b3f8f228fa54cb30c1298a91"){throw "tracked setup digest mismatch"}

  Write-Host "RELEASE_SOURCE_DOCS_VALIDATION=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
